# imports
import random
from matplotlib import pyplot as plt

class FrozenLakeEnv:
  def __init__(self):

    # grid world conditions
    self.rows = 4
    self.cols = 4
    self.initial_state = (0, 0)  # start state s_00
    self.goal_state = (3, 3)    # goal state s_33
    self.hole_states = [(0, 3), (1, 1), (3, 0), (3, 2)]
    self.curr_state= self.initial_state  # current state of the agent
    self.action_map = {'r': (0, 1), 'l': (0, -1), 'u': (-1, 0), 'd': (1, 0)}

  ### User-defined function 1: calculate manhattan distance between 2 states
  def manhattan_dist(self, state1, state2):
    x1, y1 = state1
    x2, y2 = state2
    return abs(x1 - x2) + abs(y1 - y2)

  ### User-defined function 2: return expected state after doing given action
  def expected_state_with_action(self, state, action):
    return tuple(map(lambda x, y: x + y, state, action)) # (ex. S(0, 0) + A(0, 1) = S(0, 1))

  ### User-defined function 3: get all valid adjacent states
  def get_adjacent_states(self, state):
    row, col = state
    adjacent_states = []
    possible_moves = self.action_map.values()

    for move in possible_moves:
      new_row, new_col = row + move[0], col + move[1]

      if 0 <= new_row < self.rows and 0 <= new_col < self.cols:
        adjacent_states.append((new_row, new_col))

    return adjacent_states

  # return the initial state of this MDP ...
  def reset(self):
    self.curr_state= self.init_state
    return self.curr_state

  # return a list containing all the possible states in this MDP
  def states_space(self):
    return [(i, j) for i in range(self.rows) for j in range(self.cols)]

  # return a list containing all the possible actions corresponding to the given state
  def actions_space(self, state):

    # generalization of answer in Q1.1-(a)
    if state in self.hole_states or state == self.goal_state:
      return []  # no actions available for terminal states

    x, y = state
    valid_actions = []
    if x > 0:
      valid_actions.append('u')  # up
    if x < self.rows - 1:
      valid_actions.append('d')  # down
    if y > 0:
      valid_actions.append('l')  # left
    if y < self.cols - 1:
      valid_actions.append('r')  # right

    return valid_actions

  # sparse reward function
  def sparse_reward(self, state, action, next_state):

    # return R(s, a, s’)
    return 1000 if next_state == self.goal_state else 0

  # dense reward function
  def dense_reward(self, state, action, next_state):

    # return R(s, a, s’)
    if next_state in self.hole_states:
      return -1000
    return -self.manhattan_dist(next_state, self.goal_state) + 10

  # transition probability function
  def pr(self, state, action, next_state):

    # return P(s’ | s, a)
    if state in self.hole_states or state == self.goal_state:
      return 0 # no transitions for terminal states

    # Check if the next_state is within bounds
    if not (0 <= next_state[0] < self.rows and 0 <= next_state[1] < self.cols):
      return 0

    valid_actions = self.actions_space(state)
    if action not in valid_actions: # not available action
      return 0

    ### Useful variables
    num_actions = len(valid_actions) # number of possible actions of the input state (ex. S(0, 0) = len(['r', 'd']) = 2)
    intended_action = self.action_map[action] # get intended actions from dict (ex. 'r': (0, 1))
    intended_state = self.expected_state_with_action(state, intended_action) # get expected state with given state and action (ex. S(0, 0) + A(0, 1) = S(0, 1))

    # Get probability of each case
    if next_state == intended_state: # transition succeeds
      return 2/3
    elif next_state in self.get_adjacent_states(state): # transition fails
      return 1 / (3 * (num_actions - 1))
    else:
      return 0

  def step(self, action):

    # validate the action
    valid_actions = self.actions_space(self.curr_state)
    if action not in valid_actions:
      raise ValueError("Invalid action")

    # determine the intended next state and all possible next states
    intended_action = self.action_map[action]
    intended_next_state = self.expected_state_with_action(self.curr_state, intended_action)
    all_possible_states = self.get_adjacent_states(self.curr_state)
    num_moves = len(all_possible_states)  # number of valid adjacent states

    # define the probability distribution
    probabilities = {}
    if num_moves > 1:  # at least 2 valid moves
      probabilities[intended_next_state] = 2 / 3  # twice probability for the intended move
      remaining_prob = 1 / (3 * (num_moves - 1))  # equal probability for other valid moves
      for state in all_possible_states:
        if state != intended_next_state:
          probabilities[state] = remaining_prob
    else:  # for terminal states (goal or hole), no transitions
      probabilities[self.curr_state] = 1

    # choose the next state based on the defined probabilities
    next_state = random.choices(list(probabilities.keys()), weights=list(probabilities.values()), k=1)[0]

    # Compute the rewards
    sparse_reward = self.sparse_reward(self.curr_state, action, next_state)
    dense_reward = self.dense_reward(self.curr_state, action, next_state)

    # Check termination status
    terminated = next_state in self.hole_states or next_state == self.goal_state

    # Update the current state
    self.curr_state = next_state

    # Return results
    return next_state, sparse_reward, dense_reward, terminated

# performs the given action in the MDP
def step_Grace(self, action):

  # Check action availability
  if action not in self.actions_space(self.curr_state):
    raise ValueError("Invalid action")

  # Get intended next state and all possible next states with given action
  intended_action = self.action_map[action]
  intended_next_state = self.expected_state_with_action(self.curr_state, intended_action)
  all_possible_states = self.get_adjacent_states(self.curr_state)
  num_moves = len(all_possible_states)  # number of all possible states

  # Define the probability distribution based on the number of valid moves
  if num_moves >= 2:
    probabilities = {
        possible_state: self.pr(self.curr_state, action, intended_next_state) for possible_state in all_possible_states
    }

  # If no valid moves (hole or goal state), the next state doesn't change
  else:
    probabilities = {self.curr_state: 1}

  # Choose next state with weighted randomness
  next_state = random.choices(list(probabilities.keys()), weights=list(probabilities.values()), k=1)[0]

  # Compute rewards
  sparse_reward = self.sparse_reward(self.curr_state, action, next_state)
  dense_reward = self.dense_reward(self.curr_state, action, next_state)
  terminated = (next_state in self.hole_states or next_state == self.goal_state)

  # Updates
  self.curr_state = next_state # update before the next step

  return next_state, sparse_reward, dense_reward, terminated

